<script setup>
import {nextTick,onBeforeUnmount,ref} from 'vue';import MarketIcon from './MarketIcon.vue';import ReportForm from './ReportForm.vue';import {trapDialogFocus} from '../../utils/dialogFocus.js';import {lockBodyScroll} from '../../utils/bodyScrollLock.js';
defineProps({storeId:{type:Number,required:true}});const dialog=ref(null);let opener,unlock;
async function open(event){opener=event.currentTarget;unlock=lockBodyScroll();dialog.value.showModal();await nextTick();const details=dialog.value.querySelector('details');if(details)details.open=true;dialog.value.querySelector('select')?.focus();}
function close(){unlock?.();unlock=undefined;opener?.isConnected&&opener.focus({preventScroll:true});}onBeforeUnmount(()=>{dialog.value?.close();unlock?.();});
</script>
<template><div class="bm-messages-report"><button type="button" @click="open"><MarketIcon name="flag"/> Báo cáo</button><dialog ref="dialog" class="bm-messages-report-dialog" aria-labelledby="bm-messages-report-title" @keydown.tab="trapDialogFocus" @close="close"><h2 id="bm-messages-report-title">Báo cáo gian hàng</h2><p>Gửi yêu cầu xem xét qua quy trình F19. Nội dung hội thoại không tự động đính kèm báo cáo.</p><ReportForm :key="storeId" target-type="STORE" :target-id="storeId"/><button type="button" @click="dialog.close()">Đóng</button></dialog></div></template>
<style scoped>.bm-messages-report>button,.bm-messages-report-dialog>button{display:flex;gap:8px;align-items:center;border:1px solid var(--bm-border);border-radius:8px;color:var(--bm-forest);background:var(--bm-surface);font:14px var(--bm-font);min-height:40px;padding:8px 12px;cursor:pointer}.bm-messages-report-dialog{width:min(560px,calc(100% - 28px));max-height:calc(100dvh - 32px);overflow:auto;padding:24px;border:1px solid var(--bm-border);border-radius:16px;background:var(--bm-surface);color:var(--bm-ink);box-shadow:var(--bm-shadow-dialog)}.bm-messages-report-dialog::backdrop{background:var(--bm-scrim)}.bm-messages-report-dialog h2{font-size:23px;color:var(--bm-forest)}.bm-messages-report-dialog p{line-height:1.6;font-size:14px}.bm-messages-report-dialog>button{margin-top:20px}.bm-messages-report :focus-visible{outline:3px solid var(--bm-forest);outline-offset:3px}</style>
